<?php
declare(strict_types=1);require_once __DIR__.'/auth.php';require_login();$pdo=db();if(!user_can('settings.manage')){http_response_code(403);die('Access denied.');}if(!table_exists($pdo,'communication_templates'))redirect('upgrade_phase6.php');$msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post_string('name');$body=post_string('body');if($name&&$body){$s=$pdo->prepare('INSERT INTO communication_templates(name,channel,subject,body,status,created_by) VALUES(?,?,?,?,"active",?)');$s->execute([$name,post_string('channel','email'),post_string('subject')?:null,$body,current_user()['id']]);activity($pdo,'create','communication_templates',$pdo->lastInsertId(),'Communication template created');flash('success','Template created.');}redirect('communication_templates.php');}
$rows=$pdo->query('SELECT * FROM communication_templates ORDER BY id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communication Templates</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;padding:18px 28px;border-bottom:1px solid #e5eaf2}.wrap{max-width:1050px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px;box-sizing:border-box}.field textarea{min-height:150px}.btn{background:#315ee7;color:#fff;border:0;padding:10px 14px;border-radius:8px;font-weight:800}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}</style></head><body><header class="top"><b>SPS CRM · Communication Templates</b> · <a href="dashboard.php">Dashboard</a></header><main class="wrap"><?php if($msg):?><p><?=$msg?></p><?php endif;?><div class="grid"><div class="card"><h2>New Template</h2><form method="post"><?=csrf_field()?><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Channel</label><select name="channel"><option>email</option><option>portal</option><option>internal</option><option>sms</option><option>whatsapp</option><option>voice</option></select></div><div class="field"><label>Subject</label><input name="subject"></div><div class="field"><label>Body</label><textarea name="body" required></textarea></div><button class="btn">Create</button></form></div><div class="card"><h2>Templates</h2><table class="table"><tr><th>Name</th><th>Channel</th><th>Subject</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['channel'])?></td><td><?=e($r['subject']?:'—')?></td></tr><?php endforeach;?></table></div></div></main></body></html>
